"use client";
import{useCallback,useEffect,useState}from"react";import{AppShell}from"../ui/app-shell";import{getSupabaseBrowserClient}from"../../lib/supabase/client";import{usePlayerData}from"../../lib/use-player-data";import"../resilience.css";
type Player={id:string;display_name:string|null;email:string};type Snapshot={id:string;player_id:string;checksum:string;record_counts:Record<string,number>;created_at:string};
export default function SettingsPage(){const{profile}=usePlayerData();const coach=profile?.role==="coach"||profile?.role==="admin";const[players,setPlayers]=useState<Player[]>([]);const[target,setTarget]=useState("");const[snapshots,setSnapshots]=useState<Snapshot[]>([]);const[busy,setBusy]=useState(false);const[message,setMessage]=useState("");
 const load=useCallback(async()=>{const sb=getSupabaseBrowserClient();if(!sb||!profile)return;let options:Player[]=[{id:profile.id,display_name:profile.display_name,email:profile.email}];if(coach){const{data:links}=await sb.from("coach_player_links").select("player_id").eq("coach_id",profile.id);const ids=(links||[]).map(item=>item.player_id);if(ids.length){const{data}=await sb.from("profiles").select("id,display_name,email").in("id",ids).order("display_name");options=(data||[])as Player[]}}setPlayers(options);setTarget(current=>current&&options.some(item=>item.id===current)?current:options[0]?.id||"")},[profile,coach]);const loadSnapshots=useCallback(async()=>{const sb=getSupabaseBrowserClient();if(!sb||!target)return;const{data,error}=await sb.from("player_backup_snapshots").select("id,player_id,checksum,record_counts,created_at").eq("player_id",target).order("created_at",{ascending:false});if(error)setMessage(error.message);else setSnapshots((data||[])as Snapshot[])},[target]);useEffect(()=>{const timer=setTimeout(()=>void load(),0);return()=>clearTimeout(timer)},[load]);useEffect(()=>{const timer=setTimeout(()=>void loadSnapshots(),0);return()=>clearTimeout(timer)},[loadSnapshots]);
 const download=async()=>{const sb=getSupabaseBrowserClient();if(!sb||!target)return;setBusy(true);const{data,error}=await sb.rpc("export_player_data",{target_player:target});setBusy(false);if(error){setMessage(error.message);return}const player=players.find(item=>item.id===target);const blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),anchor=document.createElement("a");anchor.href=url;anchor.download=`vector-data-${(player?.display_name||"player").replace(/[^a-z0-9]+/gi,"-").toLowerCase()}-${new Date().toISOString().slice(0,10)}.json`;anchor.click();URL.revokeObjectURL(url);setMessage("Data export downloaded to this device.")};const backup=async()=>{const sb=getSupabaseBrowserClient();if(!sb||!target)return;setBusy(true);const{error}=await sb.rpc("create_player_backup",{target_player:target});setBusy(false);setMessage(error?error.message:"Recovery snapshot created and integrity checked.");if(!error)await loadSnapshots()};
 return <AppShell active="settings"><header className="page-heading"><div><p className="eyebrow">Package 7H.2 · Privacy and recovery</p><h1>Your data. Visible and recoverable.</h1><p>Export a readable copy, create a protected recovery snapshot and understand exactly how Vector handles player information.</p></div></header>{message&&<div className="success-banner" role="status" aria-live="polite">{message}</div>}{coach&&<section className="privacy-player"><label>Selected linked player<select value={target} onChange={event=>setTarget(event.target.value)}>{players.map(item=><option value={item.id} key={item.id}>{item.display_name||item.email}</option>)}</select></label></section>}<div className="privacy-grid"><section className="privacy-panel"><p className="eyebrow">Portable copy</p><h2>Download player data</h2><p>Creates a structured JSON copy of rounds, performance results, programmes, practice records, retests, diagnostic decisions and TrackMan data.</p><button className="primary-action" disabled={!target||busy} onClick={download}>Download data export</button></section><section className="privacy-panel"><p className="eyebrow">Logical backup</p><h2>Create recovery snapshot</h2><p>Stores a versioned database snapshot with an integrity checksum. Only the player and linked coach can read it. The latest five are retained.</p><button className="primary-action" disabled={!target||busy} onClick={backup}>Create snapshot</button></section></div><section className="snapshot-panel"><div className="section-heading"><div><p className="eyebrow">Recovery history</p><h2>Protected snapshots</h2></div><span>{snapshots.length}/5 retained</span></div>{snapshots.map(item=><article key={item.id}><div><strong>{new Date(item.created_at).toLocaleString()}</strong><span>Checksum {item.checksum}</span></div><div>{Object.entries(item.record_counts||{}).map(([key,value])=><span key={key}><b>{value}</b>{key.replaceAll("_"," ")}</span>)}</div></article>)}{!snapshots.length&&<p className="empty-copy">No recovery snapshots yet.</p>}</section><section className="privacy-notice"><p className="eyebrow">Plain-language privacy</p><h2>How information is handled</h2><div><article><strong>Who can see it</strong><p>Players see their own information. Coaches see only players explicitly linked to them. Approved prescriptions are separated from private coach working notes.</p></article><article><strong>What is stored</strong><p>Account details, golf performance, programme delivery, feedback and imported TrackMan measurements needed to provide the service.</p></article><article><strong>Offline data</strong><p>Pending rounds may remain on the device until synchronised. The Sync page shows and controls those records.</p></article><article><strong>Recovery</strong><p>Snapshots are for controlled recovery. They are never silently restored or used to overwrite current information.</p></article></div></section></AppShell>}
